  return <div className="mt-8 grid gap-8 lg:grid-cols-[18rem_minmax(0,1fr)]"><form onSubmit={load} className="grid content-start gap-4 border border-white/15 bg-white/5 p-5"><p className="text-[10px] font-bold tracking-[.18em] text-[#c79a3b] uppercase">{view}</p><label className="text-xs text-white/60">TICKER<input value={ticker} onChange={event => setTicker(event.target.value.toUpperCase())} required className="mt-2 w-full border border-white/20 bg-transparent px-3 py-2 text-sm text-white" /></label>{isDcf && <><Field name="projectionYears" label="Projection years" type="number" defaultValue="5" /><Field name="baseGrowth" label="Base growth" type="number" defaultValue="0.05" /><Field name="baseDiscount" label="Base discount" type="number" defaultValue="0.1" /><Field name="baseTerminal" label="Base terminal" type="number" defaultValue="0.025" /></>}<button className="border border-[#c79a3b] bg-[#c79a3b] px-3 py-2 text-[10px] font-bold tracking-[.16em] text-[#101010] uppercase">{isDcf ? "Calculate" : "Load research"}</button>{isDcf && <p className="text-xs text-white/45">Inputs are not saved.</p>}</form><section className="border border-white/15">{error ? <p role="alert" className="p-5 text-sm text-[#ff9f7d]">{error}</p> : !data ? <p className="p-5 text-sm text-white/55">Enter a ticker to load this view.</p> : view === "technical" ? <div className="grid grid-cols-2 divide-x divide-y divide-white/15 md:grid-cols-4"><Metric label="Last" value={data.technical.latest === null ? "—" : `$${data.technical.latest.toFixed(2)}`} /><Metric label="Return" value={data.technical.returnPct === null ? "—" : `${data.technical.returnPct.toFixed(2)}%`} /><Metric label="RSI 14" value={data.technical.rsi14 === null ? "—" : data.technical.rsi14.toFixed(1)} /><Metric label="EMA 50" value={data.technical.ema50 === null ? "—" : data.technical.ema50.toFixed(2)} /></div> : view === "competitive" ? <div className="divide-y divide-white/10">{data.comparables.map((row: any) => <div key={row.ticker} className="flex justify-between gap-4 p-5"><span className="font-mono text-sm text-white">{row.ticker}</span><span className="text-xs text-[#c79a3b]">{row.price === null ? "—" : `$${row.price.toFixed(2)} · ${row.changePct?.toFixed(2) ?? "—"}%`}</span></div>)}</div> : view === "corporate structure" ? <div className="divide-y divide-white/10"><div className="p-5"><p className="font-mono text-lg text-white">{data.companyName ?? data.ticker}</p><p className="mt-2 text-xs text-white/55">CIK {data.cik ?? "—"} · Shares {data.sharesOutstanding?.toLocaleString() ?? "—"}</p></div>{data.filings.map((filing: any) => <p key={`${filing.form}-${filing.filingDate}`} className="p-5 text-sm text-white/65">{filing.form} · {filing.filingDate}</p>)}</div> : <div className="grid divide-x divide-y divide-white/15 md:grid-cols-3">{data.scenarios.map((scenario: any) => <Metric key={scenario.label} label={`${scenario.label} value`} value={scenario.perShareValue === null ? "—" : `$${scenario.perShareValue.toFixed(2)} (${scenario.upsidePct?.toFixed(1) ?? "—"}%)`} />)}</div>}</section></div>;
