function QuantArtifactPanel({ api }: { api: string }) {
  const [notice, setNotice] = useState(""); const [saving, setSaving] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); setSaving(true); setNotice(""); try { const modelId = String(form.get("modelId") ?? ""); const file = form.get("file"); const response = file instanceof File && file.size ? await fetch(`${api}/api/v1/quant/models/${encodeURIComponent(modelId)}/backtests/upload`, { method: "POST", credentials: "include", body: form }) : await fetch(`${api}/api/v1/quant/models/${encodeURIComponent(modelId)}/backtests`, { method: "POST", credentials: "include", headers: { "content-type": "application/json" }, body: JSON.stringify({ label: form.get("label"), periodType: form.get("periodType"), artifactUri: form.get("artifactUri") || undefined, artifact: JSON.parse(String(form.get("artifact") ?? "")) }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error ?? "Unable to import artifact"); event.currentTarget.reset(); setNotice(`Imported ${body.data.label}.`); } catch (reason) { setNotice(reason instanceof Error ? reason.message : "Unable to import artifact"); } finally { setSaving(false); } }
  return <form onSubmit={submit} className="mt-8 grid max-w-3xl gap-4 border border-white/15 bg-white/5 p-6"><p className="text-[10px] font-bold tracking-[.18em] text-[#c79a3b] uppercase">Import backtest evidence</p><ResourceSelect api={api} path="quant/models" name="modelId" label="Model" required /><Field name="label" label="Run label" required /><label className="text-xs text-white/60">PERIOD<select name="periodType" className="mt-2 w-full border border-white/20 bg-transparent px-3 py-2 text-sm text-white"><option value="seen">Seen</option><option value="unseen">Unseen</option></select></label><Field name="artifactUri" label="Artifact URI (optional)" /><label className="text-xs text-white/60">BACKTEST FILE (JSON, OPTIONAL)<input name="file" type="file" accept="application/json,.json" className="mt-2 block w-full text-xs text-white/70" /></label><label className="text-xs text-white/60">BACKTEST JSON (WHEN NOT UPLOADING)<textarea name="artifact" rows={9} className="mt-2 w-full border border-white/20 bg-transparent px-3 py-2 font-mono text-xs text-white outline-none focus:border-[#c79a3b]" placeholder='{"totalPerformance": ..., "state": ...}' /></label><button disabled={saving} className="border border-[#c79a3b] bg-[#c79a3b] px-3 py-2 text-[10px] font-bold tracking-[.16em] text-[#101010] uppercase disabled:opacity-50">{saving ? "Importing…" : "Import evidence"}</button>{notice && <p className="text-xs text-white/65">{notice}</p>}</form>;
}

