  useEffect(() => { load(); }, [load]);
  async function invite(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const response = await fetch(`${api}/api/v1/ops/invitations`, { method: "POST", credentials: "include", headers: { "content-type": "application/json" }, body: JSON.stringify({ email: form.get("email") }) }); const result = await response.json(); if (!response.ok) { setNotice(result.error ?? "Unable to create invitation"); return; } setNotice(`Invite code for ${result.data.email}: ${result.data.inviteCode}`); event.currentTarget.reset(); load(); }
  async function update(memberId: string, body: object) { const response = await fetch(`${api}/api/v1/ops/members/${memberId}`, { method: "PATCH", credentials: "include", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }); const result = await response.json(); if (!response.ok) { setNotice(result.error ?? "Unable to update member"); return; } setNotice("Member updated."); load(); }
