  async function create(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const response = await fetch(`${api}/api/v1/ops/workflow-templates`, { method: "POST", credentials: "include", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: form.get("name"), description: form.get("description") || "" }) }); const result = await response.json(); if (!response.ok) { setNotice(result.error ?? "Unable to create template"); return; } event.currentTarget.reset(); setNotice(`Created ${result.data.name}.`); load(); }
