function WorkflowRunsPanel({ api }: { api: string }) {
  const [run, setRun] = useState<{ template_name: string; project_name: string | null; due_at: string; tasks: Array<{ id: string; title: string; status: string; owner_name: string | null }> } | null>(null); const [notice, setNotice] = useState("");
  async function load(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const runId = String(new FormData(event.currentTarget).get("runId") ?? ""); const response = await fetch(`${api}/api/v1/ops/workflow-runs/${encodeURIComponent(runId)}`, { credentials: "include" }); const result = await response.json(); if (!response.ok) { setNotice(result.error ?? "Unable to load workflow run"); return; } setRun(result.data); setNotice(""); }
  return <section className="mt-8 border border-white/15 bg-white/5 p-5"><p className="text-[10px] font-bold tracking-[.18em] text-[#c79a3b] uppercase">Workflow run</p><form onSubmit={load} className="mt-4 max-w-xl"><ResourceSelect api={api} path="ops/workflow-runs" name="runId" label="Run" required /><button className="border border-[#c79a3b] px-3 py-2 text-[10px] font-bold tracking-[.16em] text-[#c79a3b] uppercase">Load run</button></form>{notice && <p role="alert" className="mt-3 text-xs text-[#ff9f7d]">{notice}</p>}{run && <div className="mt-6"><p className="font-mono text-sm text-white">{run.template_name}{run.project_name ? ` · ${run.project_name}` : ""}</p><p className="mt-1 text-xs text-[#c79a3b]">Due {new Date(run.due_at).toLocaleString()}</p><div className="mt-4 divide-y divide-white/10 border border-white/15">{run.tasks.map(task => <div key={task.id} className="flex justify-between gap-4 p-4 text-sm text-white/70"><span>{task.title}{task.owner_name ? ` · ${task.owner_name}` : ""}</span><span className="text-xs text-[#c79a3b] uppercase">{task.status}</span></div>)}{!run.tasks.length && <p className="p-4 text-sm text-white/55">This run has no tasks.</p>}</div></div>}</section>;
}
